        ?stationMax a sosa:Sensor ;
                    geo:hasGeometry ?geomMax .
        ?geomMax a sf:Point .
        FILTER (year(?rtMax) = 2010)
      } GROUP BY ?stationMax ?geomMax ?rtMax ?medianValMax
      ORDER BY DESC(?medianValMax)
      LIMIT 1
    }
    {
      SELECT ?stationMin ?geomMin ?rtMin ?medianValMin WHERE {
        ?stationMin a sosa:Sensor .
        ?stationAnnualResultMin sosa:observedProperty hyobs:TotalOrganicCarbon ;
                                sosa:resultTime ?rtMin ;
                                hyobs:qMedian ?medianValMin .
        ?stationMin a sosa:Sensor ;
                    geo:hasGeometry ?geomMin .
        ?geomMin a sf:Point .
        FILTER (year(?rtMin) = 2010)
      } GROUP BY ?stationMin ?geomMin ?rtMin ?medianValMin
      ORDER BY ASC(?medianValMin)
      LIMIT 1
    }
    ?geomMax geo:asWKT ?wktMax .
    ?geomMin geo:asWKT ?wktMin .
    BIND(geof:distance(?wktMax, ?wktMin) AS ?distance)
