  {
    {
      SELECT ?catchment (MAX(xsd:decimal(?val)) AS ?medianPO4P)
      WHERE {
        ?obs a sosa:Observation ;
            sosa:observedProperty hyobs:PO4PConcentrationMedian ;
            hyobs:hasAnalyte chebi:18367 ;
            sosa:hasFeatureOfInterest ?catchment ;
            sosa:resultTime ?t ;
